create function public.asset_manager_activate(p_teacher_token text,p_asset_id uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare c public.asset_candidates%rowtype;missing_partner text;
begin
 select * into c from public.asset_candidates where asset_id=p_asset_id for update;
 if not found then raise exception 'Candidate not found.';end if;
 if c.paired_asset_group is not null then
  select r.asset_key into missing_partner from public.asset_registry_projection r
  where r.paired_asset_group=c.paired_asset_group and r.asset_key<>c.asset_key
    and (r.active_version is distinct from c.version or not exists(
      select 1 from public.asset_candidates p where p.asset_key=r.asset_key and p.version=c.version
      and p.published_at is not null and p.status in('APPROVED','ACTIVE','SUPERSEDED')))
  order by r.asset_key limit 1;
  if missing_partner is not null then raise exception 'Paired asset is not activation-ready: %',missing_partner;end if;
 end if;
 return public.asset_manager_activate_pre022(p_teacher_token,p_asset_id);
end$$;

create or replace function public.asset_manager_rollback(p_teacher_token text,p_asset_id uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare c public.asset_candidates%rowtype;
begin
 if not exists(select 1 from public.s1_rooms where teacher_token_hash=public.s1_hash_token(p_teacher_token)) then raise exception 'Invalid teacher authority.';end if;
 select * into c from public.asset_candidates where asset_id=p_asset_id for update;
 if not found or c.status not in('APPROVED','SUPERSEDED') or c.published_at is null then raise exception 'Rollback target is not eligible.';end if;
 update public.asset_candidates set status='APPROVED' where asset_id=p_asset_id;
 return public.asset_manager_activate(p_teacher_token,p_asset_id);
end$$;

create or replace function public.asset_manager_sync_registry(p_teacher_token text,p_registry_sha256 text,p_assets jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare a jsonb;computed text;total int;distinct_total int;
begin
 perform public.asset_manager_assert_reviewer(p_teacher_token);
 if jsonb_typeof(p_assets)<>'array' then raise exception 'Invalid registry projection.';end if;
 select count(*),count(distinct x->>'asset_key') into total,distinct_total from jsonb_array_elements(p_assets)x;
 if total<>distinct_total or exists(select 1 from jsonb_array_elements(p_assets)x where coalesce(x->>'asset_key','')='' or x->>'asset_type' not in('image','audio')) then raise exception 'Registry contains duplicate or invalid keys.';end if;
 computed:=encode(extensions.digest(convert_to(p_assets::text,'UTF8'),'sha256'),'hex');if computed<>p_registry_sha256 then raise exception 'Registry content hash mismatch.';end if;
 delete from public.asset_registry_projection r where not exists(select 1 from jsonb_array_elements(p_assets)x where x->>'asset_key'=r.asset_key);
 for a in select * from jsonb_array_elements(p_assets) loop
  insert into public.asset_registry_projection(asset_key,display_name,aliases,asset_type,latest_version,active_version,continuity_refs,paired_asset_group,required_anchors,runtime_required,registry_sha256,projected_at)
  values(a->>'asset_key',a->>'display_name',coalesce(a->'aliases','[]'),a->>'asset_type',coalesce((a->>'latest_version')::int,0),(a->>'active_version')::int,coalesce(a->'continuity_refs','[]'),a->>'paired_asset_group',coalesce(a->'required_anchors','[]'),coalesce((a->>'runtime_required')::boolean,true),computed,now())
  on conflict(asset_key) do update set display_name=excluded.display_name,aliases=excluded.aliases,asset_type=excluded.asset_type,latest_version=excluded.latest_version,active_version=excluded.active_version,continuity_refs=excluded.continuity_refs,paired_asset_group=excluded.paired_asset_group,required_anchors=excluded.required_anchors,runtime_required=excluded.runtime_required,registry_sha256=computed,projected_at=now();
 end loop;return jsonb_build_object('ok',true,'asset_count',total,'registry_sha256',computed);
end$$;

create or replace function public.asset_manager_import_candidate(p_asset_key text,p_candidate jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.asset_registry_projection%rowtype;c public.asset_candidates%rowtype;v int;
begin
 select * into r from public.asset_registry_projection where asset_key=p_asset_key for update;
 if not found then raise exception 'ASSET KEY NOT FOUND';end if;
 v:=(p_candidate->>'version')::int;
 if v<>r.latest_version or p_candidate->>'asset_type'<>r.asset_type or p_candidate->>'sha256'!~'^[0-9a-f]{64}$' then raise exception 'Candidate identity mismatch.';end if;
 select * into c from public.asset_candidates where asset_key=p_asset_key and version=v for update;
 if found then
  if c.sha256 is distinct from p_candidate->>'sha256'
   or c.asset_type is distinct from p_candidate->>'asset_type'
   or c.mime_type is distinct from p_candidate->>'mime_type'
   or c.width_px is distinct from (p_candidate->>'width_px')::int
   or c.height_px is distinct from (p_candidate->>'height_px')::int
   or c.duration_ms is distinct from (p_candidate->>'duration_ms')::int
   or c.loopable is distinct from (p_candidate->>'loopable')::boolean
  then raise exception 'Conflicting candidate replay identity.';end if;
  return jsonb_build_object('ok',true,'asset_id',c.asset_id,'status',c.status,'reused',true);
 end if;
 insert into public.asset_candidates(asset_key,version,asset_type,creator,status,final_prompt,revision_note,technical_notes,paired_asset_group,view_name,ui_anchors,width_px,height_px,mime_type,duration_ms,loopable,license_source,loudness_note,continuity_refs,required_anchors,sha256)
 values(p_asset_key,v,r.asset_type,coalesce(p_candidate->>'creator','VA'),'UPLOADED',p_candidate->>'final_prompt',p_candidate->>'revision_note',p_candidate->>'technical_notes',r.paired_asset_group,p_candidate->>'view_name',coalesce(p_candidate->'ui_anchors','[]'),(p_candidate->>'width_px')::int,(p_candidate->>'height_px')::int,p_candidate->>'mime_type',(p_candidate->>'duration_ms')::int,(p_candidate->>'loopable')::boolean,p_candidate->>'license_source',p_candidate->>'loudness_note',r.continuity_refs,r.required_anchors,p_candidate->>'sha256') returning * into c;
 insert into public.asset_events(asset_key,event_type,version,details) values(c.asset_key,'candidate_uploaded',c.version,jsonb_build_object('asset_id',c.asset_id,'sha256',c.sha256));
 return jsonb_build_object('ok',true,'asset_id',c.asset_id,'status',c.status,'reused',false);
end$$;

create or replace function public.asset_manager_rollback_group(p_teacher_token text,p_asset_ids uuid[])
returns jsonb language plpgsql security definer set search_path=public as $$
begin
 perform public.asset_manager_assert_reviewer(p_teacher_token);
 if cardinality(p_asset_ids)=0 or exists(select 1 from public.asset_candidates where asset_id=any(p_asset_ids) and (status not in('APPROVED','SUPERSEDED') or published_at is null)) then raise exception 'Rollback group is not eligible.';end if;
 update public.asset_candidates set status='APPROVED' where asset_id=any(p_asset_ids);
 return public.asset_manager_transition_group(p_teacher_token,p_asset_ids,'rolled_back');
end$$;

create or replace function public.asset_manager_transition_group(p_teacher_token text,p_asset_ids uuid[],p_event_type text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare cand public.asset_candidates%rowtype;grp text;expected int;provided int;resolved int;missing text;
begin
 if p_event_type not in('activated','rolled_back') then raise exception 'Invalid asset transition event.';end if;
 if p_asset_ids is null or cardinality(p_asset_ids)=0 or array_position(p_asset_ids,null) is not null then raise exception 'Activation group requires non-null candidate ids.';end if;
 select count(distinct id) into provided from unnest(p_asset_ids) as u(id);
 if provided<>cardinality(p_asset_ids) then raise exception 'Activation group contains duplicate candidate ids.';end if;
 select count(*) into resolved from public.asset_candidates where asset_id=any(p_asset_ids);
 if resolved<>cardinality(p_asset_ids) then raise exception 'Activation group target does not exist.';end if;
 perform public.asset_manager_assert_reviewer(p_teacher_token);

 -- Registry rows are the canonical version authority. Lock them before the
 -- candidate rows and retain both locks through event and status writes.
 perform 1 from public.asset_registry_projection r
 where r.asset_key in(select ac.asset_key from public.asset_candidates ac where ac.asset_id=any(p_asset_ids))
 order by r.asset_key for update;
 perform 1 from public.asset_candidates where asset_id=any(p_asset_ids) order by asset_key for update;

 select count(*) into resolved from public.asset_candidates where asset_id=any(p_asset_ids);
 if resolved<>cardinality(p_asset_ids) then raise exception 'Activation group target changed during transition.';end if;
 select paired_asset_group into grp from public.asset_candidates where asset_id=p_asset_ids[1];
 if grp is null and cardinality(p_asset_ids)<>1 then raise exception 'Unpaired activation accepts one candidate.';end if;
 if grp is not null then
  select count(*) into expected from public.asset_registry_projection where paired_asset_group=grp;
  select count(*) into provided from public.asset_candidates where asset_id=any(p_asset_ids) and paired_asset_group=grp;
  if expected<>provided or provided<>cardinality(p_asset_ids) then raise exception 'Complete paired activation group is required.';end if;
 end if;
 if exists(select 1 from public.asset_candidates ac join public.asset_registry_projection r using(asset_key) where ac.asset_id=any(p_asset_ids) and (ac.status<>'APPROVED' or ac.published_at is null or r.active_version is distinct from ac.version)) then raise exception 'Activation group is not eligible.';end if;
 for cand in select * from public.asset_candidates where asset_id=any(p_asset_ids) loop
  select x into missing from jsonb_array_elements_text(cand.required_anchors)x where not exists(select 1 from jsonb_array_elements(cand.ui_anchors)a where a->>'anchor_name'=x) limit 1;
  if missing is not null then raise exception 'Required anchor is missing: %',missing;end if;
 end loop;
 insert into public.asset_events(asset_key,event_type,version,details)
 select ac.asset_key,p_event_type,ac.version,jsonb_build_object('asset_id',ac.asset_id,'paired_asset_group',ac.paired_asset_group,'group_asset_ids',to_jsonb(p_asset_ids),'previous_active_version',(select old.version from public.asset_candidates old where old.asset_key=ac.asset_key and old.status='ACTIVE' limit 1))
 from public.asset_candidates ac where ac.asset_id=any(p_asset_ids);
 update public.asset_candidates set status='SUPERSEDED' where asset_key in(select asset_key from public.asset_candidates where asset_id=any(p_asset_ids)) and status='ACTIVE';
 update public.asset_candidates set status='ACTIVE' where asset_id=any(p_asset_ids);
 return jsonb_build_object('ok',true,'activated',cardinality(p_asset_ids),'event_type',p_event_type);
end$$;

create function public.s5_submit_private_choice(p_room_code text,p_session_token text,p_client_request_id uuid,p_choice_id text) returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb;g public.game_runs%rowtype;s public.s5_run_state%rowtype;sid uuid;
begin result:=public.s5_submit_private_choice_pre029(p_room_code,p_session_token,p_client_request_id,p_choice_id);g:=public.s2_get_active_run(upper(trim(p_room_code)));select * into s from public.s5_run_state where run_id=g.run_id;if s.phase_key='act8_final_vote' then select discussion_session_id into sid from public.s5_rounds where run_id=g.run_id and phase_key=s.phase_key and vote_round=s.vote_round;perform public.s5_configure_discussion(sid,s.phase_key);update public.s3_runtime_scene_state set allow_share_photo=true where run_id=g.run_id;end if;return result;end$$;

create function public.s5_get_player_state(p_room_code text,p_session_token text) returns jsonb language plpgsql security definer set search_path=public as $$
declare base jsonb;g public.game_runs%rowtype;s public.s5_run_state%rowtype;ds jsonb;
begin base:=public.s5_get_player_state_pre029(p_room_code,p_session_token);if not coalesce((base->>'active')::boolean,false)then return base;end if;g:=public.s2_get_active_run(upper(trim(p_room_code)));select * into s from public.s5_run_state where run_id=g.run_id;select to_jsonb(d) into ds from public.discussion_sessions d join public.s5_rounds r using(discussion_session_id)where r.run_id=g.run_id and r.phase_key=s.phase_key and r.vote_round=s.vote_round;return base||jsonb_build_object('canonical_discussion',ds,'presentation_text_key',(select text_key from public.s3_runtime_scene_state where run_id=g.run_id));end$$;

create function public.s5_get_discussion_state(p_room_code text,p_session_token text) returns jsonb language plpgsql security definer set search_path=public as $$
declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;s public.s5_run_state%rowtype;ds public.discussion_sessions%rowtype;sid uuid;msgs jsonb:='[]';initials jsonb:='[]';mine jsonb;submitted int;
begin p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);select * into s from public.s5_run_state where run_id=g.run_id;if not found then return jsonb_build_object('active',false);end if;select d.* into ds from public.discussion_sessions d join public.s5_rounds r using(discussion_session_id)where r.run_id=g.run_id and r.phase_key=s.phase_key and r.vote_round=s.vote_round;if not found then return jsonb_build_object('active',true,'discussion',null);end if;sid:=ds.discussion_session_id;perform public.s2_refresh_discussion(sid);select * into ds from public.discussion_sessions where discussion_session_id=sid;
 select coalesce(jsonb_agg(jsonb_build_object('message_id',m.message_id,'display_name',rp.display_name,'role_slot',rp.role_slot,'message_text',m.message_text,'created_at',m.created_at)order by m.created_at,m.message_id),'[]')into msgs from public.dialogue_messages m join public.s1_room_players rp on rp.player_id=m.player_id where m.discussion_session_id=ds.discussion_session_id;
 select count(*)into submitted from public.s5_votes where run_id=g.run_id and phase_key=s.phase_key and vote_round=s.vote_round;select jsonb_build_object('choice_id',choice_id,'choice_label',choice_id,'locked_at',locked_at)into mine from public.s5_votes where run_id=g.run_id and phase_key=s.phase_key and vote_round=s.vote_round and player_id=p.player_id;
 if ds.show_initial_choices then select coalesce(jsonb_agg(jsonb_build_object('display_name',rp.display_name,'role_slot',rp.role_slot,'choice_id',c.choice_id,'choice_label',case c.choice_id when'main_gate'then'act08.001'when'west_tower'then'act08.002'when'compare'then'act08.003'else'act08.004'end,'locked_at',c.locked_at)order by rp.role_slot),'[]')into initials from public.s5_act8_private_choices c join public.s1_room_players rp using(player_id)where c.run_id=g.run_id;end if;
 return jsonb_build_object('active',true,'discussion',jsonb_build_object('discussion_session_id',ds.discussion_session_id,'topic',ds.topic,'status',ds.status,'vote_round',s.vote_round,'round_no',s.vote_round,'phase_deadline',ds.phase_deadline,'show_initial_choices',ds.show_initial_choices,'require_final_vote',true,'vote_options',ds.vote_options,'tie_policy',ds.tie_policy,'silent_texting_mode',true),'initial_choices',initials,'messages',msgs,'submitted_vote_count',submitted,'my_vote',mine,'revealed_votes','[]'::jsonb,'vote_history','[]'::jsonb);
end$$;

create function public.s5_audit_expire_discussion(p_room_code text,p_teacher_token text) returns jsonb language plpgsql security definer set search_path=public as $$
declare room text:=upper(trim(p_room_code));g public.game_runs%rowtype;s public.s5_run_state%rowtype;sid uuid;
begin perform public.s1_assert_teacher(room,p_teacher_token);g:=public.s2_get_active_run(room);if g.run_mode<>'audit'then raise exception'Audit timing control requires AUDIT run.';end if;select * into s from public.s5_run_state where run_id=g.run_id;select discussion_session_id into sid from public.s5_rounds where run_id=g.run_id and phase_key=s.phase_key and vote_round=s.vote_round;update public.discussion_sessions set phase_deadline=now()-interval'1 second'where discussion_session_id=sid and status='discussion';perform public.s2_refresh_discussion(sid);return jsonb_build_object('ok',true,'discussion_session_id',sid);end$$;

create function public.s5_send_message(
 p_room_code text,p_session_token text,p_expected_discussion_session_id uuid,
 p_expected_vote_round integer,p_client_request_id uuid,p_message_text text
) returns jsonb language plpgsql security definer set search_path=public as $$
declare room text:=upper(trim(p_room_code));p public.s1_room_players%rowtype;g public.game_runs%rowtype;s public.s5_run_state%rowtype;ds public.discussion_sessions%rowtype;prior public.dialogue_messages%rowtype;body text:=trim(p_message_text);m public.dialogue_messages%rowtype;
begin
 p:=public.s1_get_player_by_session(room,p_session_token);g:=public.s2_get_active_run(room);perform 1 from public.game_runs where run_id=g.run_id for update;select * into s from public.s5_run_state where run_id=g.run_id;
 select * into prior from public.dialogue_messages where run_id=g.run_id and player_id=p.player_id and client_request_id=p_client_request_id;if found then if prior.discussion_session_id<>p_expected_discussion_session_id or prior.message_text<>body then raise exception'Message request identity was reused with different content.';end if;return jsonb_build_object('ok',true,'message_id',prior.message_id,'idempotent_replay',true);end if;
 select d.* into ds from public.discussion_sessions d join public.s5_rounds r using(discussion_session_id)where d.discussion_session_id=p_expected_discussion_session_id and r.run_id=g.run_id and r.phase_key=s.phase_key and r.vote_round=p_expected_vote_round for update;
 if not found or ds.status<>'discussion' or not ds.allow_free_text then raise exception'Stale Sprint 5 discussion identity.';end if;if body=''or char_length(body)>1000 then raise exception'Message must contain 1-1000 characters.';end if;
 insert into public.dialogue_messages(run_id,discussion_session_id,scene_id,phase_key,step_key,player_id,message_text,client_request_id)values(g.run_id,ds.discussion_session_id,ds.scene_id,ds.phase_key,ds.step_key,p.player_id,body,p_client_request_id)returning * into m;
 perform public.s2_log_event(g.run_id,room,ds.discussion_session_id,'dialogue_message_sent',p.player_id,jsonb_build_object('message_id',m.message_id,'client_request_id',p_client_request_id));return jsonb_build_object('ok',true,'message_id',m.message_id,'idempotent_replay',false);
end$$;

